test("temporary login failure shows a helpful explanation and permits a successful retry", async ({
    page,
  }) => {
    await mockApi(page, "USER")
    let attempts = 0
    await page.route("**/api/auth/login", async (route) => {
      attempts++
      if (attempts === 1) {
        await route.fulfill({
          status: 503,
          json: {
            error:
              "The database is temporarily busy or unavailable. Please try again.",
          },
        })
      } else await route.fallback()
    })
    await page.goto("/login")
    await page
      .getByLabel("Email address", { exact: true })
      .fill("retry@example.com")
    await page
      .getByLabel("Password", { exact: true })
      .fill("RegressionPassword123!")
    await page.getByRole("button", { name: "Sign In", exact: true }).click()
    await expect(
      page.getByText("The server is having trouble. Please try again shortly."),
    ).toBeVisible()
    expect(await storedTokens(page)).toEqual([null, null])
    await expect(page.getByLabel("Email address", { exact: true })).toHaveValue(
      "retry@example.com",
    )
    await page.getByRole("button", { name: "Sign In", exact: true }).click()
    await expect(page).toHaveURL(/\/dashboard$/)
    expect(attempts).toBe(2)
    expect(await storedTokens(page)).toEqual(["test-session", "test-refresh"])
  })

