    quotations: [
      {
        id: "quote-1",
        version: 1,
        status: "SENT",
        scope: "Design and build a five-page website.",
        deliverables: ["Five accessible pages", "Production deployment"],
        lineItems: [
          {
            description: "Website delivery",
            quantity: 1,
            unitPrice: "25000.00",
          },
        ],
        total: "25000.00",
        currency: "PHP",
        timeline: "Six weeks",
        paymentTerms: "50% before commencement",
        paymentDue: "12500.00",
        validUntil: "2030-12-01T08:00:00.000Z",
