              lastMessage: null,
            },
          ],
          nextCursor: null,
        },
      })
    if (url.pathname === "/api/request-conversations/request-1")
      return route.fulfill({
        json: {
          conversation: {
            id: workflow.request.id,
            department: workflow.request.department,
            head: { id: "head-1", fullName: "Dani Head" },
            bookings: [
