          mandatory: true,
          amount: "12500.00",
          currency: "PHP",
          status: "PENDING",
          proofFileId: null,
          reference: null,
        }
        workflow.events.push(
          {
            id: "event-2",
            type: "APPROVAL_CONFIRMED",
            summary: "The client formally accepted quotation version 1.",
            entityId: "approval-1",
            createdAt: "2026-10-30T08:05:00.000Z",
