test("history renders the manager lifecycle statuses", async ({ page }) => {
  await page.setViewportSize({ width: 1440, height: 900 })
  await session(page)
  const statuses = [
    "SUBMITTED",
    "UNDER_REVIEW",
    "AWAITING_CLIENT_INFO",
    "READY_FOR_QUOTATION",
    "CLOSED",
    "CANCELLED",
  ] as const
  await page.route("**/api/client/service-requests?*", (route) =>
    route.fulfill({
      json: {
        requests: statuses.map((status, index) => ({
          ...request(index + 1),
          status,
        })),
        total: statuses.length,
        page: 1,
        pageSize: 10,
        summary: {
          total: 6,
          pending: 1,
          inProgress: 3,
          completed: 1,
          cancelled: 1,
        },
      },
    }),
  )
  await page.goto("/dashboard")
  await page.getByRole("link", { name: "Booked Requests", exact: true }).click()
  await expect(
    page.getByRole("heading", { name: "Booked Requests", exact: true }),
  ).toBeVisible()
  const table = page.getByRole("table")
  for (const label of [
    "Pending review",
    "Under review",
    "Awaiting your information",
    "Ready for quotation",
    "Closed",
    "Cancelled",
  ])
    await expect(table.getByText(label, { exact: true })).toBeVisible()
})

