      const dept = departments.find((d) => d.id === id)
      if (dept) {
        await route.fulfill({
          json: { department: { ...dept, members: [], teams: [] } },
        })
      } else {
        await route.fulfill({
          status: 404,
          json: { error: "Department not found" },
