    if (pathname === "/api/services" && method === "GET") {
      await route.fulfill({ json: { services } })
      return
    }
    if (pathname === "/api/client/services" && method === "GET") {
      await route.fulfill({
        json: { services: services.filter((service) => service.isActive) },
      })
      return
    }
    const clientServiceMatch = pathname.match(
      /^\/api\/client\/services\/([^/]+)$/,
    )
    if (clientServiceMatch && method === "GET") {
      const service = services.find(
        (item) => item.id === clientServiceMatch[1] && item.isActive,
      )
      await route.fulfill(
        service
          ? { json: { service } }
          : { status: 404, json: { error: "Service not found" } },
      )
      return
    }
    if (pathname === "/api/services/pricing-templates" && method === "GET") {
      await route.fulfill({
        json: {
          pricingTemplates: pricingTemplates.map((template) => ({
            ...template,
            services: services
              .filter((service) => service.pricingTemplateId === template.id)
              .map(({ id, name }) => ({ id, name })),
          })),
        },
      })
      return
    }
    const pricingTemplateMatch = pathname.match(
      /^\/api\/services\/pricing-templates\/([^/]+)$/,
    )
    if (pricingTemplateMatch && ["PUT", "DELETE"].includes(method)) {
      const template = pricingTemplates.find(
        (item) => item.id === pricingTemplateMatch[1],
      )
      if (!template) {
        await route.fulfill({
          status: 404,
          json: { error: "Pricing template not found" },
        })
        return
      }
      const linkedServices = services.filter(
        (service) => service.pricingTemplateId === template.id,
      )
      if (method === "DELETE") {
        if (linkedServices.length > 0) {
          await route.fulfill({
            status: 409,
            json: { error: "Reassign this template before deleting it." },
          })
          return
        }
        pricingTemplates.splice(pricingTemplates.indexOf(template), 1)
        await route.fulfill({ json: { success: true } })
      } else {
        const body = request.postDataJSON() as PricingConfigurationInput
        Object.assign(template, body, {
          amount: body.amount?.toFixed(2) ?? null,
        })
        for (const service of linkedServices)
          service.pricingTemplate = { ...template }
        await route.fulfill({
          json: {
            pricingTemplate: {
              ...template,
              services: linkedServices.map(({ id, name }) => ({ id, name })),
            },
          },
        })
      }
      return
    }
    if (pathname === "/api/services" && method === "POST") {
      const body = request.postDataJSON() as ServiceInput
      const service: Service = {
        id: `service-${services.length + 1}`,
        name: body.name,
        description: body.description,
        iconKey: body.iconKey,
        imageUrl: body.imageDataUrl,
        imageAltText: body.imageAltText,
        clientRequirements: body.clientRequirements,
        requiresConsultation: body.requiresConsultation,
        consultationNotes: body.consultationNotes,
        keyBenefits: body.keyBenefits.map((benefit, index) => ({
          ...benefit,
          id: `benefit-${index + 1}`,
          displayOrder: index,
        })),
        isActive: body.isActive,
        ...pricingFields(body),
        departments: departments.filter((department) =>
          body.departmentIds.includes(department.id),
        ),
        createdAt: "2026-01-02T00:00:00.000Z",
        updatedAt: "2026-01-02T00:00:00.000Z",
      }
      services.push(service)
      await route.fulfill({ status: 201, json: { service } })
      return
    }
    const serviceMatch = pathname.match(/^\/api\/services\/([^/]+)(\/status)?$/)
    if (serviceMatch && ["PUT", "PATCH", "DELETE"].includes(method)) {
      const service = services.find((item) => item.id === serviceMatch[1])
      expect(
        service,
        "Service mutation must target an existing fixture",
      ).toBeDefined()
      if (method === "DELETE") {
        services.splice(services.indexOf(service!), 1)
        await route.fulfill({ json: { success: true } })
      } else {
        const body = request.postDataJSON() as Partial<ServiceInput>
        Object.assign(
          service!,
          body,
          method === "PUT" ? pricingFields(body as ServiceInput) : {},
          method === "PUT" && body.keyBenefits
            ? {
                keyBenefits: body.keyBenefits.map((benefit, index) => ({
                  ...benefit,
                  id: `benefit-${index + 1}`,
                  displayOrder: index,
                })),
              }
            : {},
          body.departmentIds
            ? {
                departments: departments.filter((department) =>
                  body.departmentIds!.includes(department.id),
                ),
              }
            : {},
        )
        await route.fulfill({ json: { service } })
      }
      return
    }

    if (pathname === "/api/departments" && method === "POST") {
      const body = request.postDataJSON() as {
        name: string
        color: Department["color"]
        code?: string
        description?: string
        headId?: string | null
      }
      const created: Department = {
        id: `dept-${Date.now()}`,
        name: body.name,
        color: body.color,
        code: body.code ?? null,
        description: body.description ?? null,
        headId: body.headId ?? null,
        head: null,
        memberCount: 0,
        teamCount: 0,
        createdAt: new Date().toISOString(),
        updatedAt: new Date().toISOString(),
      }
      departments.push(created)
      await route.fulfill({ json: { department: created } })
      return
    }

    if (deptIdMatch && method === "PUT") {
      const id = decodeURIComponent(deptIdMatch[1])
      const body = request.postDataJSON() as Partial<Department>
      const target = departments.find((d) => d.id === id)
      if (target) {
        Object.assign(target, body, { updatedAt: new Date().toISOString() })
        await route.fulfill({ json: { department: target } })
      } else {
        await route.fulfill({
          status: 404,
          json: { error: "Department not found" },
        })
      }
      return
    }

    if (deptIdMatch && method === "DELETE") {
      const id = decodeURIComponent(deptIdMatch[1])
      const index = departments.findIndex((d) => d.id === id)
      if (index >= 0) {
        departments.splice(index, 1)
        await route.fulfill({ status: 204 })
      } else {
        await route.fulfill({
          status: 404,
          json: { error: "Department not found" },
        })
      }
      return
    }

    pageErrors.get(page)?.push(`Unhandled API request: ${method} ${pathname}`)
    await route.fulfill({
      status: 404,
      json: { error: "Unknown test endpoint" },
    })
  })

