test(`employee profile and login controls at ${width}px`, async ({
    page,
  }) => {
    await page.setViewportSize({ width, height: 900 })
    await page.emulateMedia({ reducedMotion: "reduce" })
    let employee: Employee = {
      id: "account:account-1",
      accountId: "account-1",
      hasEmployeeRecord: false,
      employeeId: "",
      fullName: "Alex Employee",
      email: "alex@example.com",
      contactNumber: "09123456789",
      position: null,
      employmentType: null,
      status: null,
      startDate: null,
      departmentId: null,
      teamId: null,
      department: null,
      team: null,
      hasAccount: true,
      accountIsActive: true,
      createdAt: "2026-01-15T00:00:00Z",
      updatedAt: "2026-01-15T00:00:00Z",
    }
    let accountDeleted = false
    let accountArchived = false
    const loginStatusWrites: boolean[] = []
    await page.addInitScript(() =>
      sessionStorage.setItem("nexus.auth.token", "test-session"),
    )
    await page.route("**/api/**", async (route) => {
      const request = route.request()
      const path = new URL(request.url()).pathname
      if (path === "/api/auth/me")
        return route.fulfill({
          json: {
            user: {
              id: "admin",
              fullName: "Admin",
              email: "admin@example.com",
              role: "ADMIN",
              isActive: true,
              permissions: [
                "employees:read",
                "employees:manage",
                "departments:read",
                "dashboard:read",
              ],
              createdAt: "2026-01-01T00:00:00Z",
            },
          },
        })
      const department = {
        id: "dept-1",
        name: "Engineering",
        code: "ENG",
        headId: null,
        head: null,
        memberCount: 1,
        teamCount: 0,
        description: null,
        createdAt: "2026-01-01T00:00:00Z",
        updatedAt: "2026-01-01T00:00:00Z",
      }
      if (path === "/api/departments")
        return route.fulfill({ json: { departments: [department] } })
