    // Feature specs can override these exact list routes with populated fixtures.
    if (
      (pathname === "/api/request-conversations" ||
        pathname === "/api/internal-conversations") &&
      method === "GET"
    ) {
      await route.fulfill({
        json: { conversations: [], nextCursor: null, unreadCount: 0 },
      })
      return
    }

    if (
      pathname === "/api/request-workflows/notifications" &&
      method === "GET"
    ) {
      await route.fulfill({ json: { notifications: [], unreadCount: 0 } })
      return
    }

    if (pathname === "/api/clients" && method === "GET") {
      const search = url.searchParams.get("search")?.toLowerCase() ?? ""
      const clients = users.filter(
        (user) =>
          user.role === "USER" &&
          `${user.fullName} ${user.email}`.toLowerCase().includes(search),
      )
      await route.fulfill({
        json: { clients, total: clients.length, page: 1, pageSize: 10 },
      })
      return
    }
    const clientMatch = pathname.match(
      /^\/api\/clients\/([^/]+)(?:\/(projects|service-requests))?$/,
    )
    if (clientMatch && method === "GET") {
      const client = users.find(
        (user) => user.id === clientMatch[1] && user.role === "USER",
      )
      if (!client)
        await route.fulfill({
          status: 404,
          json: { error: "Client not found" },
        })
      else if (clientMatch[2])
        await route.fulfill({
          json: {
            [clientMatch[2] === "projects" ? "projects" : "serviceRequests"]:
