          json: { department: { ...dept, members: [], teams: [] } },
        })
      } else {
        await route.fulfill({
          status: 404,
          json: { error: "Department not found" },
        })
      }
      return
    }

    if (pathname === "/api/departments" && method === "GET") {
      await route.fulfill({ json: { departments } })
      return
    }

