            canSend: true,
            messages: state.threadMessages.get(thread.id) ?? [],
            meetings: state.meetings.get(thread.id) ?? [],
            nextCursor: null,
          },
        })
    }
    return route.fulfill({ status: 404, json: { error: "Unexpected request" } })
  })

