          approveQuotation: false,
          verifyPayment: false,
        },
        requirements: [],
        files: [],
        consultations: [],
        quotations: [],
        approval: null,
        agreement: null,
        payment: null,
        project: null,
        events: workflowBooking
          ? [
              {
