    if (workflowThread) {
      const workflow: Workflow = {
        request: {
          id: workflowThread.id,
          referenceNumber: workflowThread.referenceNumber,
          title: workflowThread.title,
          serviceName: workflowThread.service.name,
          packageName: null,
