          expectedTimeline: "Six weeks",
          client: workflowThread.client,
          department: workflowThread.acceptedDepartment,
        },
        state:
          workflowBooking?.workflowState ??
          (workflowThread.status === "CANCELLED"
            ? "CANCELLED"
            : workflowThread.status === "CLOSED"
