    if (url.pathname === "/api/auth/settings")
      return route.fulfill({
        json: { preferences: defaultPreferences, sessions: [] },
      })
    if (url.pathname === "/api/request-conversations") {
      state.listReads++
      if (state.listError)
        return route.fulfill({
          status: 503,
          json: { error: "Couldn't load conversations." },
        })
