                state.conversations ??
                (state.accepted
                  ? [
                      {
                        id: booking.id,
                        status: booking.status,
                        title: booking.title,
                        referenceNumber: null,
                        updatedAt: booking.updatedAt,
                        service: booking.service,
                        client: { id: "client-1", fullName: "Mara Client" },
                        acceptedDepartment: {
                          id: "design",
