    const pathname = url.pathname
    expect(url.origin).toBe(new URL(page.url()).origin)

    if (pathname === "/api/auth/login" && method === "POST") {
      const data = request.postDataJSON() as {
        email?: string
        password?: string
      }
      if (
        data.email === "invalid@example.com" ||
        data.password === "WrongPassword123!"
      ) {
        await route.fulfill({
          status: 401,
          json: {
            error: "Email or password is incorrect. Please try again.",
          },
        })
        return
      }
      await route.fulfill({
        json: {
          token: "test-session",
          refreshToken: "test-refresh",
          user: currentUser,
          expiresIn: 900,
        },
      })
      return
    }

    if (pathname === "/api/auth/register" && method === "POST") {
      const data = request.postDataJSON() as { email?: string }
      if (data.email === "duplicate@example.com") {
        await route.fulfill({
          status: 409,
          json: {
            error: "This email is already registered. Sign in instead.",
          },
        })
        return
      }
      await route.fulfill({
        status: 201,
        json: {
          token: "test-session",
          refreshToken: "test-refresh",
          user: currentUser,
          expiresIn: 900,
        },
      })
      return
    }

    expect(request.headers().authorization).toBe(
      `Bearer ${options?.accessToken?.() ?? "test-session"}`,
