                {
                  id: "maria",
                  fullName: "Maria Santos",
                  position: "UI/UX Designer",
                  status: "ACTIVE",
                  profileSpecialties: ["Figma", "Research"],
                  team: null,
                  capacity: saved
                    ? { scheduledHours: 40, timeOffHours: 8 }
                    : null,
                  assignments: allocated
                    ? [
                        {
                          id: "assignment-1",
                          projectId: "project-1",
                          employeeId: "maria",
                          weeklyHours: 10,
                          allocationStart: null,
                          allocationEnd: null,
                          project: {
                            id: "project-1",
                            name: "Website Redesign",
                            status: "IN_PROGRESS",
                          },
                        },
                        ...(multiple
                          ? [
                              {
                                id: "assignment-2",
                                projectId: "project-2",
                                employeeId: "maria",
                                weeklyHours: overloaded ? 40 : 2,
                                allocationStart: null,
                                allocationEnd: null,
                                project: {
                                  id: "project-2",
                                  name: "Brand Identity",
                                  status: "IN_PROGRESS",
                                },
                              },
                            ]
                          : []),
                      ]
                    : [],
                },
              ],
        },
      })
    return route.fulfill({ json: { notifications: [], unreadCount: 0 } })
  })
  await page.goto("/staff-workload")
  await expect(
    page.getByRole("heading", { name: "Staff Workload", exact: true }),
