      const targetIndex = users.findIndex((u) => u.id === targetId)
      if (targetIndex >= 0 && users[targetIndex]?.accountDeletedAt) {
        users.splice(targetIndex, 1)
        await route.fulfill({
          json: { message: "Account permanently deleted" },
