      const target = users.find((u) => u.id === targetId)
      if (target && !target.isActive && !target.accountDeletedAt) {
        target.accountDeletedAt = new Date().toISOString()
        await route.fulfill({ json: { message: "Account moved to trash" } })
      } else {
