import { defineConfig, devices } from "@playwright/test"
import { existsSync } from "node:fs"
import { fileURLToPath } from "node:url"

const credentialsPath = fileURLToPath(
  new URL(".env.regression.local", import.meta.url),
)
if (existsSync(credentialsPath)) process.loadEnvFile(credentialsPath)
const live = process.env.NEXUS_E2E_LIVE === "1"
const baseURL = process.env.NEXUS_E2E_BASE_URL || "http://127.0.0.1:5273"

export default defineConfig({
  testDir: "./e2e",
  testMatch: "**/*.spec.ts",
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  workers: live ? 1 : undefined,
  use: {
    baseURL,
    trace: live ? "off" : "retain-on-failure",
  },
  projects: [
    {
      name: "chromium",
      use: {
        ...devices["Desktop Chrome"],
        channel: process.env.PLAYWRIGHT_CHANNEL,
      },
    },
  ],
  webServer: process.env.NEXUS_E2E_BASE_URL
    ? undefined
    : {
        command: "pnpm build && node scripts/start.mjs",
        url: "http://127.0.0.1:5273",
        env: {
          NODE_ENV: "production",
          PORT: "5273",
          HOSTNAME: "127.0.0.1",
        },
        reuseExistingServer: false,
        timeout: 120_000,
      },
})

import { spawn } from "node:child_process"
import { existsSync } from "node:fs"
import { join } from "node:path"

const windowsPnpm = join(
  process.env.APPDATA ?? "",
  "npm",
  "node_modules",
  "pnpm",
  "pnpm.exe",
)
const packageManager =
  process.platform === "win32" && existsSync(windowsPnpm)
    ? windowsPnpm
    : process.platform === "win32"
      ? "pnpm.cmd"
      : "pnpm"
const useShellFallback =
  process.platform === "win32" && packageManager === "pnpm.cmd"
const playwrightArguments = process.argv.slice(2)

function run(name, args) {
  let child
  try {
    child = spawn(packageManager, args, {
      env: process.env,
      shell: useShellFallback,
      stdio: "inherit",
    })
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error)
    console.error(`[${name}] failed to start: ${message}`)
    return Promise.resolve({ code: 1, name })
  }

  return new Promise((resolve) => {
    child.once("error", (error) => {
      console.error(`[${name}] failed to start: ${error.message}`)
      resolve({ code: 1, name })
    })
    child.once("close", (code, signal) => {
      resolve({ code: code ?? 1, name, signal })
    })
  })
}

const results = await Promise.all([
  run("backend regression", ["--filter", "@nexus/api", "test:regression"]),
  run("Playwright", [
    "--filter",
    "@nexus/web",
    "test:e2e",
    ...playwrightArguments,
  ]),
])

const failures = results.filter((result) => result.code !== 0)
if (failures.length > 0) {
  for (const failure of failures) {
    const reason = failure.signal
      ? `signal ${failure.signal}`
      : `exit code ${failure.code}`
    console.error(`${failure.name} failed with ${reason}.`)
  }
  process.exitCode = 1
}

import { access } from "node:fs/promises"
import path from "node:path"
import { pathToFileURL } from "node:url"

const appRoot = path.resolve(import.meta.dirname, "..")
const serverPath = path.join(
  appRoot,
  ".next",
  "standalone",
  "apps",
  "web",
  "server.js",
)

try {
  await access(serverPath)
} catch {
  throw new Error('Standalone server not found. Run "pnpm build" first.')
}

process.env.HOSTNAME ||= "0.0.0.0"
process.env.PORT ||= "5173"

await import(pathToFileURL(serverPath).href)

import { cp, mkdir } from "node:fs/promises"
import path from "node:path"

const appRoot = path.resolve(import.meta.dirname, "..")
const standaloneAppRoot = path.join(
  appRoot,
  ".next",
  "standalone",
  "apps",
  "web",
)

async function copyDirectory(source, destination) {
  await mkdir(path.dirname(destination), { recursive: true })
  await cp(source, destination, { recursive: true, force: true })
}

await Promise.all([
  copyDirectory(
    path.join(appRoot, "public"),
    path.join(standaloneAppRoot, "public"),
  ),
  copyDirectory(
    path.join(appRoot, ".next", "static"),
    path.join(standaloneAppRoot, ".next", "static"),
  ),
])

import type { NextConfig } from "next"
import path from "node:path"

const staticAssetCsp = [
  "default-src 'none'",
  "base-uri 'none'",
  "form-action 'none'",
  "frame-ancestors 'none'",
  "object-src 'none'",
].join("; ")

const nextConfig: NextConfig = {
  output: "standalone",
  poweredByHeader: false,
  outputFileTracingRoot: path.resolve(import.meta.dirname, "../.."),
  // Native DLLs/DSOs loaded by Sharp are not all discovered by file tracing.
  outputFileTracingIncludes: {
    "/*": [
      "../../node_modules/.pnpm/@img+sharp-*/node_modules/@img/sharp-*/lib/**/*",
    ],
  },
  images: {
    qualities: [70, 75],
    remotePatterns: [
      {
        protocol: "https",
        hostname: "*.supabase.co",
        pathname: "/storage/v1/object/public/**",
      },
      {
        protocol: "https",
        hostname: "*.supabase.com",
        pathname: "/storage/v1/object/public/**",
      },
    ],
  },
  async headers() {
    return [
      {
        source: "/:path*",
        headers: [
          {
            key: "X-Content-Type-Options",
            value: "nosniff",
          },
        ],
      },
      {
        source: "/_next/static/:path*",
        headers: [
          {
            key: "Content-Security-Policy",
            value: staticAssetCsp,
          },
        ],
      },
    ]
  },
  async rewrites() {
    const apiOrigin = (
      process.env.API_PROXY_TARGET || "http://localhost:3001"
    ).replace(/\/$/, "")

    return [{ source: "/api/:path*", destination: `${apiOrigin}/api/:path*` }]
  },
}

export default nextConfig

import type { Account } from "./types"

export const Permissions = {
  DASHBOARD_READ: "dashboard:read",
  PROFILE_READ: "profile:read",
  PROFILE_CHANGE_PASSWORD: "profile:change-password",
  ACCOUNTS_READ: "accounts:read",
  ACCOUNTS_RESET_PASSWORD: "accounts:reset-password",
  ACCOUNTS_CREATE_BASIC: "accounts:create-basic",
  ACCOUNTS_CREATE_PRIVILEGED: "accounts:create-privileged",
  ACCOUNTS_ASSIGN_BASIC: "accounts:assign-basic",
  ACCOUNTS_ASSIGN_PRIVILEGED: "accounts:assign-privileged",
  ACCOUNTS_STATUS_BASIC: "accounts:status-basic",
  ACCOUNTS_STATUS_PRIVILEGED: "accounts:status-privileged",
  DEPARTMENTS_READ: "departments:read",
  DEPARTMENTS_MANAGE: "departments:manage",
  DEPARTMENTS_DELETE: "departments:delete",
  EMPLOYEES_READ: "employees:read",
  EMPLOYEES_MANAGE: "employees:manage",
  SERVICES_READ: "services:read",
  SERVICES_MANAGE: "services:manage",
  CLIENTS_READ: "clients:read",
} as const

export type Permission = (typeof Permissions)[keyof typeof Permissions]

type Role = Account["role"]

function isPrivileged(role: Role): boolean {
  return role === "ADMIN" || role === "SUPERADMIN"
}

export function hasPermission(
  account: Account,
  permission: Permission,
): boolean {
  return account.permissions?.includes(permission) ?? false
}

export function canAccessAccountManagement(account: Account): boolean {
  return (
    account.role === "SUPERADMIN" &&
    hasPermission(account, Permissions.ACCOUNTS_READ)
  )
}

export function canAccessDepartmentManagement(account: Account): boolean {
  return (
    account.role === "ADMIN" &&
    hasPermission(account, Permissions.DEPARTMENTS_READ)
  )
}

export function canAccessEmployeeManagement(account: Account): boolean {
  return (
    account.role === "ADMIN" &&
    hasPermission(account, Permissions.EMPLOYEES_READ)
  )
}

export function canAccessServiceManagement(account: Account): boolean {
  return (
    account.role === "ADMIN" &&
    hasPermission(account, Permissions.SERVICES_READ)
  )
}

export function canAccessServiceCatalog(account: Account): boolean {
  return account.role === "USER"
}

export function canAccessBookedServices(account: Account): boolean {
  return account.role === "USER"
}

export function canAccessRequestInbox(account: Account): boolean {
  return account.role === "STAFF" && !!account.headOf
}

export function canAccessMessages(account: Account): boolean {
  return (
    account.role === "USER" ||
    account.role === "ADMIN" ||
    account.role === "SUPERADMIN" ||
    account.role === "STAFF"
  )
}

export function canAccessProjects(account: Account): boolean {
  return account.role === "USER" || account.role === "STAFF"
}

export function canAccessProjectWorkspace(account: Account): boolean {
  return account.role === "STAFF"
}

export function canCreateProjectWorkspace(account: Account): boolean {
  return account.role === "STAFF" && Boolean(account.headOf)
}

export function canAccessClientManagement(account: Account): boolean {
  return (
    account.role === "ADMIN" && hasPermission(account, Permissions.CLIENTS_READ)
  )
}

export function canCreateRole(actor: Account, role: Role): boolean {
  return hasPermission(
    actor,
    isPrivileged(role)
      ? Permissions.ACCOUNTS_CREATE_PRIVILEGED
      : Permissions.ACCOUNTS_CREATE_BASIC,
  )
}

export function canAssignRole(
  actor: Account,
  current: Role,
  next: Role,
): boolean {
  return hasPermission(
    actor,
    isPrivileged(current) || isPrivileged(next)
      ? Permissions.ACCOUNTS_ASSIGN_PRIVILEGED
      : Permissions.ACCOUNTS_ASSIGN_BASIC,
  )
}

export function canChangeAccountStatus(
  actor: Account,
  target: Account,
): boolean {
  return (
    actor.id !== target.id &&
    hasPermission(
      actor,
      isPrivileged(target.role)
        ? Permissions.ACCOUNTS_STATUS_PRIVILEGED
        : Permissions.ACCOUNTS_STATUS_BASIC,
    )
  )
}

export function canChangeAccountPassword(
  actor: Account,
  target: Account,
): boolean {
  return (
    actor.role === "SUPERADMIN" &&
    actor.id !== target.id &&
    !target.accountDeletedAt &&
    hasPermission(actor, Permissions.ACCOUNTS_RESET_PASSWORD)
  )
}
